Stock stock = {500, 200, 40, 3};
printf("%d\n", stock.water_ml);
stock.water_ml = 450;
printf("%d\n", stock.water_ml);

Stock stock_after_water_use(
Stock stock, int amount_ml)
{
if (amount_ml >= 0 &&
amount_ml <= stock.water_ml)
{
stock.water_ml -= amount_ml;
}
return stock;
}

bool can_make_coffee(
Stock stock, Recipe recipe)
{
return
stock.water_ml >= recipe.water_ml &&
stock.milk_ml >= recipe.milk_ml &&
stock.beans_g >= recipe.beans_g &&
stock.paper_cups >= recipe.paper_cups;
}

Stock stock_after_coffee(
Stock stock, Recipe recipe)
{
if (can_make_coffee(stock, recipe))
{
stock.water_ml -= recipe.water_ml;
stock.milk_ml -= recipe.milk_ml;
stock.beans_g -= recipe.beans_g;
stock.paper_cups -= recipe.paper_cups;
}
return stock;
}

